void Registry(const std::shared_ptr<const dt::TimestampValidatedProfileHandleV3>& profile){unsigned admitted=0,refused=0;for(const auto& fixture:kClassifications){Check(dt::ClassifyTimestampIntrinsicOperationV3(fixture.operation)==fixture.disposition,"sealed intrinsic row");admitted+=fixture.disposition==dt::TimestampIntrinsicDispositionV3::admitted;refused+=fixture.disposition==dt::TimestampIntrinsicDispositionV3::registered_refused;}Check(admitted==28&&refused==5,"28 admitted and five refused intrinsic rows");Check(dt::ClassifyTimestampIntrinsicOperationV3(static_cast<dt::TimestampIntrinsicOperationV3>(0xff))==dt::TimestampIntrinsicDispositionV3::unknown,"unknown operation classification");dt::TimestampValueViewV3 poison{profile.get(),dt::TimestampValueStateV3::value,0,~p::u64{0}};auto unknown=dt::RefuseTimestampIntrinsicOperationV3(poison,static_cast<dt::TimestampIntrinsicOperationV3>(0xff));Check(!unknown.ok()&&unknown.diagnostic.diagnostic_code=="CTI.TEMPORAL.OPERATION_REFUSED","unknown intrinsic refuses without PRESENT payload access");auto invalid_profile=*profile;invalid_profile.profile_fingerprint[0]^=1;dt::TimestampValueViewV3 wrong_authority{&invalid_profile,dt::TimestampValueStateV3::value,0,0};unknown=dt::RefuseTimestampIntrinsicOperationV3(wrong_authority,static_cast<dt::TimestampIntrinsicOperationV3>(0xff));Check(!unknown.ok()&&unknown.diagnostic.diagnostic_code=="CTI.TEMPORAL.DESCRIPTOR_INVALID","authority validation precedes unknown intrinsic classification");dt::TimestampValueViewV3 dirty_null{profile.get(),dt::TimestampValueStateV3::sql_null,1,0};unknown=dt::RefuseTimestampIntrinsicOperationV3(dirty_null,static_cast<dt::TimestampIntrinsicOperationV3>(0xff));Check(!unknown.ok()&&unknown.diagnostic.diagnostic_code=="DATATYPE.NULL_STATE.INVALID","dirty NULL validation precedes unknown intrinsic classification");for(const auto& fixture:kClassifications)if(fixture.disposition==dt::TimestampIntrinsicDispositionV3::registered_refused){auto r=dt::RefuseTimestampIntrinsicOperationV3({profile.get(),dt::TimestampValueStateV3::sql_null,0,0},fixture.operation);const bool calendar=fixture.operation==dt::TimestampIntrinsicOperationV3::calendar_interval_arithmetic||fixture.operation==dt::TimestampIntrinsicOperationV3::bucketing;Check(!r.ok()&&r.diagnostic.diagnostic_code==(calendar?"CTI.INTERVAL.CALENDAR_OPERATION_REFUSED":"CTI.TEMPORAL.OPERATION_REFUSED"),"registered refusal uses operation-specific diagnostic without NULL propagation");}}

void CivilAndFacts(const std::shared_ptr<const dt::TimestampValidatedProfileHandleV3>& profile){auto value=dt::ConstructTimestampFromCivilV3(profile,2024,2,29,6,7,8,900'000'000);Check(value.ok()&&value.value.civil_day==19782&&value.value.nanoseconds_since_midnight==22'028'900'000'000ull,"civil construct");auto civil=dt::DecomposeTimestampCivilV3(value.value.view());Check(civil.ok()&&civil.civil.year==2024&&civil.civil.month==2&&civil.civil.day==29&&civil.civil.hour==6&&civil.civil.minute==7&&civil.civil.second==8&&civil.civil.nanosecond==900'000'000,"civil decompose");Check(dt::ExtractTimestampYearV3(value.value.view()).signed_value==2024,"extract year");Check(dt::ExtractTimestampMonthV3(value.value.view()).unsigned_value==2,"extract month");Check(dt::ExtractTimestampDayV3(value.value.view()).unsigned_value==29,"extract day");Check(dt::ExtractTimestampHourV3(value.value.view()).unsigned_value==6,"extract hour");Check(dt::ExtractTimestampMinuteV3(value.value.view()).unsigned_value==7,"extract minute");Check(dt::ExtractTimestampSecondV3(value.value.view()).unsigned_value==8,"extract second");Check(dt::ExtractTimestampNanosecondV3(value.value.view()).unsigned_value==900'000'000,"extract nanosecond");Check(dt::TimestampDayCountV3(value.value.view()).signed_value==19782,"extract day count");Check(dt::TimestampNanosecondOfDayV3(value.value.view()).unsigned_value==22'028'900'000'000ull,"extract nanosecond of day");Check(dt::TimestampIsLeapYearV3(value.value.view()).boolean_value,"leap year");Check(dt::TimestampDaysInMonthV3(value.value.view()).unsigned_value==29,"days in month");Check(dt::TimestampIsoWeekdayV3(value.value.view()).unsigned_value==4,"ISO weekday");Check(dt::TimestampDayOfYearV3(value.value.view()).unsigned_value==60,"day of year");Check(dt::TimestampQuarterV3(value.value.view()).unsigned_value==1,"quarter");auto week=dt::TimestampIsoWeekV3(value.value.view());Check(week.ok()&&week.value.iso_year==2024&&week.value.iso_week==9,"ISO week");Check(dt::TruncateTimestampNanosecondV3(value.value).value.nanoseconds_since_midnight==value.value.nanoseconds_since_midnight&&dt::RoundTimestampNanosecondV3(value.value).value.nanoseconds_since_midnight==value.value.nanoseconds_since_midnight,"nanosecond truncate/round identity");Check(dt::ConstructTimestampFromCivilV3(profile,2024,0,29,0,0,0,0).diagnostic.diagnostic_code=="CTI.TEMPORAL.ZERO_DATE_REFUSED"&&dt::ConstructTimestampFromCivilV3(profile,2024,2,0,0,0,0,0).diagnostic.diagnostic_code=="CTI.TEMPORAL.ZERO_DATE_REFUSED","zero month/day use reserved semantic diagnostic");Check(dt::ConstructTimestampFromCivilV3(profile,2024,2,29,24,0,0,0).diagnostic.diagnostic_code=="CTI.TEMPORAL.INVALID_LITERAL","hour 24 refused");Check(dt::ConstructTimestampFromCivilV3(profile,2024,2,29,23,59,60,0).diagnostic.diagnostic_code=="CTI.TEMPORAL.LEAP_SECOND_REFUSED","leap second refused");Check(dt::ConstructTimestampFromCivilV3(profile,std::numeric_limits<std::int64_t>::min(),1,1,0,0,0,0).diagnostic.diagnostic_code=="CTI.TEMPORAL.RANGE_EXCEEDED","INT64_MIN January year refuses without signed overflow");Check(dt::ConstructTimestampFromCivilV3(profile,std::numeric_limits<std::int64_t>::max(),2,1,0,0,0,0).diagnostic.diagnostic_code=="CTI.TEMPORAL.RANGE_EXCEEDED","INT64_MAX February year refuses deterministically");dt::TimestampNullableI64FactV3 bad_year{dt::TimestampI64CarrierKindV3::wrong_host_type,static_cast<dt::TimestampValueStateV3>(255),0};dt::TimestampNullableUnsignedFactV3 bad_part{dt::TimestampUnsignedCarrierKindV3::wrong_host_type,static_cast<dt::TimestampValueStateV3>(255),0};Check(dt::ConstructTimestampFromCivilV3({},bad_year,bad_part,bad_part,bad_part,bad_part,bad_part,bad_part).diagnostic.diagnostic_code=="SBLR.OPERAND_INVALID","civil carriers precede profile and state");}

void Arithmetic(const std::shared_ptr<const dt::TimestampValidatedProfileHandleV3>& profile){dt::TimestampOwnedValueV3 epoch{profile,dt::TimestampValueStateV3::value,0,0};auto previous=dt::SubtractTimestampNanosecondsV3(epoch,1);Check(previous.ok()&&previous.value.civil_day==-1&&previous.value.nanoseconds_since_midnight==86'399'999'999'999ull,"subtract across midnight uses Euclidean remainder");auto next=dt::AddTimestampNanosecondsV3(previous.value,1);Check(next.ok()&&next.value.civil_day==0&&next.value.nanoseconds_since_midnight==0,"add across midnight");auto negative=dt::AddTimestampNanosecondsV3(epoch,-1);Check(negative.ok()&&negative.value.civil_day==-1&&negative.value.nanoseconds_since_midnight==86'399'999'999'999ull,"negative add across midnight");Check(dt::TimestampSuccessorV3(previous.value).value.civil_day==0,"successor across day boundary");Check(dt::TimestampPredecessorV3(epoch).value.civil_day==-1,"predecessor across day boundary");dt::TimestampOwnedValueV3 minimum{profile,dt::TimestampValueStateV3::value,INT32_MIN,0},maximum{profile,dt::TimestampValueStateV3::value,INT32_MAX,86'399'999'999'999ull};Check(!dt::TimestampPredecessorV3(minimum).ok()&&!dt::TimestampSuccessorV3(maximum).ok(),"successor/predecessor bounds");Check(!dt::AddTimestampNanosecondsV3(minimum,std::numeric_limits<std::int64_t>::min()).ok(),"INT64_MIN addition never negates operand");Check(!dt::SubtractTimestampNanosecondsV3(maximum,std::numeric_limits<std::int64_t>::min()).ok(),"INT64_MIN subtraction never negates operand");auto forward=dt::DifferenceTimestampV3(maximum.view(),minimum.view());Check(forward.ok()&&!forward.is_null&&!forward.difference.negative&&forward.difference.magnitude_whole_days==4'294'967'295ull&&forward.difference.magnitude_nanoseconds_remainder==86'399'999'999'999ull,"full-domain positive private difference");auto reverse=dt::DifferenceTimestampV3(minimum.view(),maximum.view());Check(reverse.ok()&&reverse.difference.negative&&reverse.difference.magnitude_whole_days==4'294'967'295ull&&reverse.difference.magnitude_nanoseconds_remainder==86'399'999'999'999ull,"full-domain negative private difference");auto zero=dt::DifferenceTimestampV3(epoch.view(),epoch.view());Check(zero.ok()&&!zero.difference.negative&&zero.difference.magnitude_whole_days==0&&zero.difference.magnitude_nanoseconds_remainder==0,"zero difference has nonnegative sign");dt::TimestampOwnedValueV3 null_value{profile,dt::TimestampValueStateV3::sql_null,0,0};auto null_diff=dt::DifferenceTimestampV3(null_value.view(),maximum.view());Check(null_diff.ok()&&null_diff.is_null,"clean NULL difference propagation");dt::TimestampOwnedValueV3 poisoned_present{profile,dt::TimestampValueStateV3::value,0,~p::u64{0}};auto null_before_present=dt::DifferenceTimestampV3(null_value.view(),poisoned_present.view());Check(null_before_present.ok()&&null_before_present.is_null,"difference clean NULL propagates without other PRESENT payload access");dt::TimestampNullableI64FactV3 null_delta{dt::TimestampI64CarrierKindV3::signed_i64,dt::TimestampValueStateV3::sql_null,0};auto add_null=dt::AddTimestampNanosecondsV3(poisoned_present,null_delta);Check(add_null.ok()&&add_null.value.state==dt::TimestampValueStateV3::sql_null,"add clean NULL delta propagates without timestamp PRESENT payload access");auto subtract_null=dt::SubtractTimestampNanosecondsV3(poisoned_present,null_delta);Check(subtract_null.ok()&&subtract_null.value.state==dt::TimestampValueStateV3::sql_null,"subtract clean NULL delta propagates without timestamp PRESENT payload access");}

void ParseLocalCivil(const std::shared_ptr<const dt::TimestampValidatedProfileHandleV3>& profile){auto parsed=dt::ParseCanonicalTimestampV3(profile,"2024-02-29T06:07:08.9");Check(parsed.ok()&&dt::RenderCanonicalTimestampV3(parsed.value).text=="2024-02-29T06:07:08.9","parse/render roundtrip");constexpr std::array<std::string_view,12> invalid{{"2024-02-29 06:07:08","2024-02-29t06:07:08","2024-02-29T06:07:08Z","2024-02-29T06:07:08+00:00","2024-02-29T24:00:00","2024-02-29T23:59:60","2024-02-29T06:07:08.900","2024-02-29T06:07:08.1234567890","2024-00-01T00:00:00","2024-02-30T00:00:00"," 2024-02-29T00:00:00","2024-02-29T00:00:00 "}};for(auto text:invalid)Check(!dt::ParseCanonicalTimestampV3(profile,text).ok(),"strict local-civil grammar refuses zone/offset/noncanonical text");auto literal=dt::RenderCanonicalTimestampV3(parsed.value,true);Check(literal.ok()&&literal.text=="TIMESTAMP '2024-02-29T06:07:08.9'","inert SQL export literal");}
